import base64
data = base64.b64decode("p0EG6TCIe9XiRlDrM4ot07lBBrwykgymljQ=")
key_hex = bytes.fromhex("72dae74be9008f35")
key_ascii = b"72dae74be9008f35"

def xor(d, k):
    return bytes(b ^ k[i % len(k)] for i, b in enumerate(d))

for name, k in [("hex-bytes", key_hex), ("ascii", key_ascii)]:
    for variant, d in [("raw", data), ("reversed", data[::-1])]:
        out = xor(d, k)
        print(f"{name:10} {variant:9} -> {out!r}")
EOF

